export interface TourRegistryItem {
  /** Exact string used in `data-tour` attributes. */
  key: TourKey;
  area: TourArea;
  /** Human-readable label for documentation and authoring tools. */
  label: string;
  /** Short description of the element this key targets. */
  description: string;
  /** Whether this key must be placed before Wave 1 ships. */
  requiredForV1: boolean;
  /** IDs of the V1 tutorials that require this element to be reachable. */
  tutorials: RequiredTutorialId[];
}

